            new Quote { Id = "https://hi.wikiquote.org/wiki/महादेवी_वर्मा", Text = "काँटों का स्थान जब चरणों के नीचे रहता है तभी वे टूट कर दूसरों को बेधने की शक्ति खोते हैं । परीक्षाएँ जब मनुष्य के मानसिक स्वास्थ्य को क्षत-विक्षत कर डालती हैं तब उन्हें उतीर्ण होने-न-होने का कोई मूल्य नहीं रह जाता ।", Author = "महादेवी वर्मा" },
