            new Quote { Id = "https://hi.wikiquote.org/wiki/महादेवी_वर्मा", Text = "अपने दलों पर मोती सा जल भी न ठहरने देने वाली कमल की सीमातीत स्वच्छता ही उसे पंक में जमने की शक्ति देती है।", Author = "महादेवी वर्मा" },
