            new Quote { Id = "https://hi.wikiquote.org/wiki/महादेवी_वर्मा", Text = "पाँच जल की धाराओं से घिरा और रंग-बिरंगे फूलों में छिपे चरणों से लेकर शून्य नीलिमा में प्रकट मस्तक तक सफेद हिम में समाधिस्थ केदार का पर्वत देखा वे ही उसका आकर्षण जान सकते हैं। मीलों दूर से ही वह उज्ज्वल शिखर अक्षरहीन आमंत्रण के समान खुला दिखाई देता है।", Author = "महादेवी वर्मा" },
